using UnityEngine;

/// <summary>
/// 技能数据资产（ScriptableObject）。
/// 右键 -> Create -> Game -> Skill Data 创建。
/// </summary>
[CreateAssetMenu(fileName = "NewSkill", menuName = "Game/Skill Data")]
public class SkillData : ScriptableObject
{
    [Header("基本信息")]
    public string skillId;          // 唯一标识，如 "fireball"
    public string skillName;        // 显示名称
    [TextArea] public string description;
    public Sprite icon;

    [Header("数值")]
    public float cooldown = 2f;           // 基础冷却时间（秒）
    public float castRange = 10f;         // 施法距离
    public float damageMultiplier = 1.5f; // 伤害系数（乘以施法者攻击力）
    public int maxLevel = 5;              // 最大升级等级

    [Header("效果策略")]
    public SkillEffectBase skillEffect;   // 拖入具体效果资产，如 ProjectileSkillEffect
}

using UnityEngine;

/// <summary>
/// 技能效果抽象基类 — 策略模式的核心。
/// 每个具体效果都是一个独立的 ScriptableObject 资产。
/// </summary>
public abstract class SkillEffectBase : ScriptableObject
{
    /// <summary>
    /// 执行技能效果。
    /// </summary>
    /// <param name="caster">施法者接口（玩家或敌人）</param>
    /// <param name="direction">施法方向（已归一化）</param>
    /// <param name="damageMultiplier">经过等级加成后的最终伤害系数</param>
    /// <param name="ownerType">施法者类型，用于投射物区分敌我</param>
    public abstract void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType);
}

using System;
using UnityEngine;

/// <summary>
/// 技能运行时实例，持有 SkillData + 等级 + 冷却状态。
/// 通过 OnExecute 委托注入具体释放效果。
/// </summary>
public class SkillInstance
{
    public SkillData Data { get; private set; }
    public int Level { get; private set; } = 1;
    public int MaxLevel => Data.maxLevel;
    public bool IsMaxLevel => Level >= MaxLevel;
    public bool IsCoolingDown { get; private set; }

    private float _cooldownRemaining;

    /// <summary>剩余冷却秒数（供 UI 读取）</summary>
    public float CooldownRemaining => _cooldownRemaining;

    /// <summary>冷却进度 0~1，1=满冷却（刚释放），0=冷却完毕（供 UI 读取）</summary>
    public float CooldownPercent
    {
        get
        {
            float total = CurrentCooldown;
            return total > 0f ? Mathf.Clamp01(_cooldownRemaining / total) : 0f;
        }
    }

    /// <summary>当前等级冷却时间（每级减少10%）</summary>
    public float CurrentCooldown => Data.cooldown * (1f - (Level - 1) * 0.1f);

    /// <summary>当前等级伤害系数</summary>
    public float CurrentDamageMultiplier => Data.damageMultiplier * (1f + (Level - 1) * 0.15f);

    /// <summary>技能执行委托：参数为 (施法者, 目标方向)</summary>
    public event Action<ISkillCaster, Vector2> OnExecute;

    internal SkillInstance(SkillData data)
    {
        Data = data;
        Level = 1;
    }

    /// <summary>每帧驱动冷却</summary>
    public void TickCooldown(float deltaTime)
    {
        if (!IsCoolingDown) return;
        _cooldownRemaining -= deltaTime;
        if (_cooldownRemaining <= 0f)
        {
            IsCoolingDown = false;
            _cooldownRemaining = 0f;
        }
    }

    /// <summary>尝试释放技能，返回是否成功</summary>
    public bool TryCast(ISkillCaster caster, Vector2 targetDirection)
    {
        if (IsCoolingDown) return false;

        IsCoolingDown = true;
        _cooldownRemaining = CurrentCooldown;

        OnExecute?.Invoke(caster, targetDirection);
        return true;
    }

    /// <summary>升级技能，返回是否成功</summary>
    public bool TryUpgrade()
    {
        if (IsMaxLevel) return false;
        Level++;
        return true;
    }
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// 技能库（ScriptableObject）—— 所有技能的唯一工厂入口。
/// 右键 -> Create -> Game -> Skill Library 创建。
/// </summary>
[CreateAssetMenu(fileName = "SkillLibrary", menuName = "Game/Skill Library")]
public class SkillLibrary : ScriptableObject
{
    [SerializeField] private List<SkillData> _allSkills;

    /// <summary>所有技能列表</summary>
    public IReadOnlyList<SkillData> AllSkills => _allSkills;

    /// <summary>通过 ID 查找技能数据</summary>
    public SkillData GetById(string skillId)
    {
        return _allSkills?.Find(s => s.skillId == skillId);
    }

    /// <summary>
    /// 创建完整可用的技能实例（SkillLibrary 是唯一工厂入口）。
    /// 通过 skillEffect 策略注入 OnExecute 委托。
    /// </summary>
    public SkillInstance CreateSkillInstance(string skillId)
    {
        SkillData data = GetById(skillId);
        if (data == null)
        {
            Debug.LogWarning($"SkillLibrary: 未找到 skillId='{skillId}'");
            return null;
        }

        SkillInstance instance = new SkillInstance(data);

        instance.OnExecute += (caster, direction) =>
        {
            if (data.skillEffect == null) return;

            Projectile.OwnerType ownerType = caster.GetOwnerType();
            data.skillEffect.Execute(caster, direction,
                instance.CurrentDamageMultiplier, ownerType);
        };

        return instance;
    }

    /// <summary>随机获取一个技能数据</summary>
    public SkillData GetRandom()
    {
        if (_allSkills == null || _allSkills.Count == 0) return null;
        return _allSkills[Random.Range(0, _allSkills.Count)];
    }

    /// <summary>
    /// 随机创建一个完整可用的技能实例（已注入 OnExecute）。
    /// </summary>
    public SkillInstance CreateRandomInstance()
    {
        SkillData data = GetRandom();
        return data != null ? CreateSkillInstance(data.skillId) : null;
    }

    /// <summary>随机获取 N 个不重复的技能数据</summary>
    public List<SkillData> GetRandomDistinct(int count)
    {
        if (_allSkills == null || _allSkills.Count == 0) return new List<SkillData>();

        var shuffled = _allSkills.OrderBy(_ => Random.value).ToList();
        int take = Mathf.Min(count, shuffled.Count);
        return shuffled.GetRange(0, take);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 技能槽位：绑定键位 + 技能实例 + 解锁状态。
/// 在 Inspector 中可配置初始键位。
/// </summary>
[Serializable]
public class SkillSlot
{
    public KeyCode keyBinding = KeyCode.None;
    public bool isUnlocked = true;

    public SkillInstance Skill { get; private set; }
    public bool IsEmpty => Skill == null;

    public void Equip(SkillInstance skill) => Skill = skill;
    public void Unequip() => Skill = null;

    /// <summary>尝试释放槽位中的技能</summary>
    public bool TryCast(ISkillCaster caster, Vector2 direction)
    {
        return Skill != null && Skill.TryCast(caster, direction);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家技能管理器，挂载在 Player GameObject 上。
/// 管理技能槽位、键位绑定、技能获取/升级/拓展。
/// </summary>
public class PlayerSkillManager : MonoBehaviour, ISkillCaster
{
    [Header("技能槽位")]
    [SerializeField] private List<SkillSlot> _slots = new()
    {
        new SkillSlot { keyBinding = KeyCode.Q },
        new SkillSlot { keyBinding = KeyCode.E },
        new SkillSlot { keyBinding = KeyCode.Z },
        new SkillSlot { keyBinding = KeyCode.X },
    };

    [Header("技能库")]
    [SerializeField] private SkillLibrary _skillLibrary;

    [Header("初始技能")]
    [Tooltip("游戏开始时自动装备的技能 ID（槽位 0~3，留空则不装备）")]
    [SerializeField] private string _initialSkillId0;
    [SerializeField] private string _initialSkillId1;
    [SerializeField] private string _initialSkillId2;
    [SerializeField] private string _initialSkillId3;

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;
    private PlayerStats _stats;

    public Vector2 GetTargetDirection()
    {
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;
        return (mouseWorldPos - transform.position).normalized;
    }

    public float GetAttackStrength() => _stats != null ? _stats.AttackStrength : 10f;

    public Projectile.OwnerType GetOwnerType() => Projectile.OwnerType.Player;

    // ---------- 委托 ----------
    /// <summary>技能释放事件：参数为 (槽位索引, 技能数据)</summary>
    public event System.Action<int, SkillData> OnSkillCast;
    /// <summary>技能升级事件</summary>
    public event System.Action<int, int> OnSkillUpgraded;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();
        EquipInitialSkills();
    }

    private void EquipInitialSkills()
    {
        var ids = new[] { _initialSkillId0, _initialSkillId1, _initialSkillId2, _initialSkillId3 };
        for (int i = 0; i < ids.Length; i++)
        {
            if (!string.IsNullOrEmpty(ids[i]))
                EquipSkill(i, ids[i]);
        }
    }

    void Update()
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            SkillSlot slot = _slots[i];
            slot.Skill?.TickCooldown(Time.deltaTime);

            if (slot.isUnlocked && Input.GetKeyDown(slot.keyBinding))
            {
                CastSkill(i);
            }
        }
    }

    // ---------- 释放 ----------
    private void CastSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return;
        SkillSlot slot = _slots[index];
        if (!slot.isUnlocked || slot.IsEmpty) return;

        Vector2 direction = GetTargetDirection();

        if (slot.TryCast(this, direction))
        {
            OnSkillCast?.Invoke(index, slot.Skill.Data);
        }
    }

    // ---------- 获取与装备 ----------
    /// <summary>从技能库获取技能并装备到第一个空槽</summary>
    public bool AcquireSkill(string skillId)
    {
        if (_skillLibrary == null) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        return instance != null && EquipToEmptySlot(instance);
    }

    /// <summary>装备技能到指定槽位</summary>
    public bool EquipSkill(int index, string skillId)
    {
        if (_skillLibrary == null) return false;
        if (index < 0 || index >= _slots.Count || !_slots[index].isUnlocked) return false;

        SkillInstance instance = _skillLibrary.CreateSkillInstance(skillId);
        if (instance == null) return false;

        _slots[index].Equip(instance);
        return true;
    }

    /// <summary>装备到第一个空槽</summary>
    public bool EquipToEmptySlot(SkillInstance skill)
    {
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].isUnlocked && _slots[i].IsEmpty)
            {
                _slots[i].Equip(skill);
                return true;
            }
        }
        return false;
    }

    // ---------- 升级 ----------
    /// <summary>升级指定槽位技能</summary>
    public bool UpgradeSkill(int index)
    {
        if (index < 0 || index >= _slots.Count) return false;
        SkillSlot slot = _slots[index];
        if (slot.IsEmpty) return false;

        if (slot.Skill.TryUpgrade())
        {
            OnSkillUpgraded?.Invoke(index, slot.Skill.Level);
            return true;
        }
        return false;
    }

    // ---------- 槽位管理 ----------
    /// <summary>拓展技能槽数量</summary>
    public void ExpandSlots(int additionalSlots)
    {
        for (int i = 0; i < additionalSlots; i++)
        {
            _slots.Add(new SkillSlot { keyBinding = KeyCode.None, isUnlocked = true });
        }
    }

    /// <summary>解锁指定槽位</summary>
    public void UnlockSlot(int index)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].isUnlocked = true;
    }

    // ---------- 键位 ----------
    /// <summary>重新绑定槽位键位</summary>
    public void RebindKey(int index, KeyCode newKey)
    {
        if (index >= 0 && index < _slots.Count)
            _slots[index].keyBinding = newKey;
    }

    /// <summary>获取槽位技能（供外部查询，如UI）</summary>
    public SkillInstance GetSkill(int index)
    {
        return (index >= 0 && index < _slots.Count) ? _slots[index].Skill : null;
    }

    /// <summary>查询槽位是否解锁（供 UI Controller 读取）</summary>
    public bool IsSlotUnlocked(int index)
    {
        return index >= 0 && index < _slots.Count && _slots[index].isUnlocked;
    }

    /// <summary>获取槽位绑定的快捷键（供 UI Controller 读取）</summary>
    public KeyCode GetKeyCode(int index)
    {
        if (index < 0 || index >= _slots.Count) return KeyCode.None;
        return _slots[index].keyBinding;
    }

    public int SlotCount => _slots.Count;
}

using System;
using UnityEngine;

/// <summary>
/// 传递给 SkillSlotView 的纯显示数据 DTO，无行为。
/// Controller 从 SkillInstance / SkillSlot 提取后传入 View。
/// </summary>
public struct SkillViewData : IEquatable<SkillViewData>
{
    public Sprite Icon;
    public string KeyLabel;
    public bool ShowKeyLabel;
    public int Level;
    public int MaxLevel;
    public bool IsEquipped;
    public bool IsUnlocked;
    public bool IsCoolingDown;
    public float CooldownPercent;
    public float CooldownRemaining;

    public bool Equals(SkillViewData other)
    {
        return ReferenceEquals(Icon, other.Icon)
            && KeyLabel == other.KeyLabel
            && Level == other.Level
            && MaxLevel == other.MaxLevel
            && IsEquipped == other.IsEquipped
            && IsUnlocked == other.IsUnlocked
            && IsCoolingDown == other.IsCoolingDown
            && ShowKeyLabel == other.ShowKeyLabel
            && Mathf.Approximately(CooldownPercent, other.CooldownPercent)
            && Mathf.Approximately(CooldownRemaining, other.CooldownRemaining);
    }

    public override bool Equals(object obj) => obj is SkillViewData other && Equals(other);

    public override int GetHashCode()
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + (Icon != null ? Icon.GetHashCode() : 0);
            hash = hash * 23 + (KeyLabel != null ? KeyLabel.GetHashCode() : 0);
            hash = hash * 23 + Level.GetHashCode();
            hash = hash * 23 + MaxLevel.GetHashCode();
            hash = hash * 23 + IsEquipped.GetHashCode();
            hash = hash * 23 + IsUnlocked.GetHashCode();
            hash = hash * 23 + IsCoolingDown.GetHashCode();
            hash = hash * 23 + CooldownPercent.GetHashCode();
            hash = hash * 23 + CooldownRemaining.GetHashCode();
            return hash;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 技能槽位 View —— 纯渲染，不引用任何游戏逻辑。
/// 由 Controller 调用 Refresh() 更新显示。
/// </summary>
public class SkillSlotView : MonoBehaviour
{
    [Header("图标与文本")]
    [SerializeField] private Image _icon;
    [SerializeField] private TMP_Text _keyLabel;
    [SerializeField] private TMP_Text _levelText;

    [Header("冷却")]
    [SerializeField] private Image _cooldownOverlay;
    [SerializeField] private TMP_Text _cooldownText;

    [Header("状态遮罩")]
    [SerializeField] private GameObject _lockedOverlay;
    [SerializeField] private GameObject _emptyOverlay;

    [Header("交互")]
    [SerializeField] private Button _upgradeButton;

    /// <summary>Controller 调用，传入数据刷新 UI</summary>
    public void Refresh(in SkillViewData data)
    {
        // 图标
        if (_icon != null)
        {
            _icon.sprite = data.Icon;
            _icon.enabled = data.Icon != null;
        }

        // 快捷键
        if (_keyLabel != null)
        {
            _keyLabel.text = data.KeyLabel;
            _keyLabel.gameObject.SetActive(data.ShowKeyLabel);
        }

        // 等级
        if (_levelText != null)
            _levelText.text = data.IsEquipped ? $"Lv.{data.Level}" : "";

        // 冷却填充 — 仅在冷却中显示，否则完全隐藏
        if (_cooldownOverlay != null)
        {
            _cooldownOverlay.fillAmount = data.CooldownPercent;
            _cooldownOverlay.enabled = data.IsCoolingDown && data.CooldownPercent > 0f;
        }

        // 冷却数字
        if (_cooldownText != null)
        {
            bool showCooldown = data.IsCoolingDown && data.CooldownRemaining > 0f;
            _cooldownText.gameObject.SetActive(showCooldown);
            if (showCooldown)
                _cooldownText.text = $"{data.CooldownRemaining:F1}s";
        }

        // 解锁/空槽遮罩
        if (_lockedOverlay != null)
            _lockedOverlay.SetActive(!data.IsUnlocked);
        if (_emptyOverlay != null)
            _emptyOverlay.SetActive(data.IsUnlocked && !data.IsEquipped);

        // 升级按钮 — 未装备或满级时隐藏
        if (_upgradeButton != null)
            _upgradeButton.gameObject.SetActive(data.IsEquipped && data.Level < data.MaxLevel);
    }
}

using UnityEngine;

/// <summary>
/// 技能 UI Controller —— 监听 PlayerSkillManager（Model），通知 SkillUIPanel（View）。
/// 本类是 Model ↔ View 的唯一耦合点。
/// </summary>
public class SkillUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private PlayerSkillManager _skillManager;

    [Header("View 引用")]
    [SerializeField] private SkillUIPanel _panel;

    private SkillViewData[] _previousData = System.Array.Empty<SkillViewData>();

    // ==================== 生命周期 ====================

    private void Start()
    {
        // 跨场景后序列化引用失效，动态查找 PlayerSkillManager
        if (_skillManager == null)
            _skillManager = ResolveSkillManager();

        if (_skillManager == null)
        {
            Debug.LogError("SkillUIController: PlayerSkillManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("SkillUIController: SkillUIPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_skillManager.SlotCount);
        _previousData = new SkillViewData[_skillManager.SlotCount];

        // 订阅 Model 事件
        _skillManager.OnSkillCast += HandleSkillCast;
        _skillManager.OnSkillUpgraded += HandleSkillUpgraded;

        // 初始全量刷新
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void Update()
    {
        if (_skillManager == null) return;

        // 每帧同步冷却变化（冷却值通过 SkillInstance 的公开属性读取）
        for (int i = 0; i < _skillManager.SlotCount; i++)
            SyncSlot(i);
    }

    private void OnDestroy()
    {
        if (_skillManager != null)
        {
            _skillManager.OnSkillCast -= HandleSkillCast;
            _skillManager.OnSkillUpgraded -= HandleSkillUpgraded;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleSkillCast(int index, SkillData data) => SyncSlot(index);
    private void HandleSkillUpgraded(int index, int newLevel) => SyncSlot(index);

    // ==================== 核心同步 ====================

    private void SyncSlot(int index)
    {
        SkillInstance skill = _skillManager.GetSkill(index);
        SkillViewData data = BuildViewData(index, skill);

        if (!data.Equals(_previousData[index]))
        {
            _previousData[index] = data;
            _panel.RefreshSlot(index, data);
        }
    }

    private SkillViewData BuildViewData(int index, SkillInstance skill)
    {
        SkillViewData data = default;

        data.IsUnlocked = _skillManager.IsSlotUnlocked(index);
        data.IsEquipped = skill != null;
        data.ShowKeyLabel = true;

        // 快捷键标签
        KeyCode key = _skillManager.GetKeyCode(index);
        data.KeyLabel = KeyCodeToString(key);

        if (skill != null)
        {
            SkillData def = skill.Data;
            data.Icon = def.icon;
            data.Level = skill.Level;
            data.MaxLevel = skill.MaxLevel;
            data.IsCoolingDown = skill.IsCoolingDown;
            data.CooldownPercent = skill.CooldownPercent;
            data.CooldownRemaining = skill.CooldownRemaining;
        }

        return data;
    }

    private static string KeyCodeToString(KeyCode key)
    {
        // 提取字母/数字部分，去除 "Alpha" 前缀
        string s = key.ToString();
        if (s.StartsWith("Alpha"))
            return s.Substring(5);
        return s;
    }

    /// <summary>运行时动态查找 PlayerSkillManager (解决跨场景序列化引用失效问题)</summary>
    private static PlayerSkillManager ResolveSkillManager()
    {
        // 优先从 PlayerManager 获取持久化 Player
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<PlayerSkillManager>();

        // 兜底: Tag 查找
        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<PlayerSkillManager>() : null;
    }
}

using UnityEngine;

/// <summary>
/// 技能 UI 面板 —— 管理 SkillSlotView 的创建与刷新。
/// </summary>
public class SkillUIPanel : MonoBehaviour
{
    [Header("预制体与容器")]
    [SerializeField] private SkillSlotView _slotPrefab;
    [SerializeField] private Transform _container;

    private SkillSlotView[] _views = System.Array.Empty<SkillSlotView>();

    /// <summary>Controller 调用，按数量创建槽位 View</summary>
    public void Initialize(int slotCount)
    {
        // 清理旧子对象
        for (int i = _container.childCount - 1; i >= 0; i--)
            SafeDestroy(_container.GetChild(i).gameObject);

        _views = new SkillSlotView[slotCount];
        for (int i = 0; i < slotCount; i++)
        {
            SkillSlotView view = Instantiate(_slotPrefab, _container);
            view.name = $"SkillSlot_{i}";
            _views[i] = view;
        }
    }

    /// <summary>Controller 调用，刷新指定槽位</summary>
    public void RefreshSlot(int index, in SkillViewData data)
    {
        if (index < 0 || index >= _views.Length) return;
        _views[index]?.Refresh(data);
    }

    /// <summary>获取指定槽位 View（供 Controller 绑定按钮事件）</summary>
    public SkillSlotView GetSlotView(int index)
    {
        if (index < 0 || index >= _views.Length) return null;
        return _views[index];
    }

    private static void SafeDestroy(Object obj)
    {
        if (obj == null) return;
        if (Application.isPlaying)
            Destroy(obj);
        else
            DestroyImmediate(obj);
    }
}

using UnityEngine;

/// <summary>
/// 投射物型技能效果：生成子弹/火球沿方向飞行，支持散射。
/// 右键 -> Create -> Game -> Skill Effect -> Projectile
/// </summary>
[CreateAssetMenu(fileName = "ProjectileEffect", menuName = "Game/Skill Effect/Projectile")]
public class ProjectileSkillEffect : SkillEffectBase
{
    [Header("投射物配置")]
    [Tooltip("投射物预制体（需挂载 Projectile 组件）")]
    public GameObject projectilePrefab;

    [Tooltip("飞行速度")]
    public float speed = 10f;

    [Tooltip("投射物数量（扇形散射）")]
    public int count = 1;

    [Tooltip("散射角度（仅 count > 1 时生效）")]
    [Range(0f, 180f)] public float spreadAngle = 30f;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        if (projectilePrefab == null)
        {
            Debug.LogWarning("ProjectileSkillEffect: projectilePrefab 为空！");
            return;
        }

        Vector3 spawnPos = caster.CasterTransform.position;
        float baseDamage = caster.GetAttackStrength() * damageMultiplier;

        if (count == 1)
        {
            SpawnOne(spawnPos, direction, baseDamage, speed, ownerType, caster);
        }
        else
        {
            float halfSpread = spreadAngle * 0.5f;
            float angleStep = count > 1 ? spreadAngle / (count - 1) : 0f;
            float baseAngle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

            for (int i = 0; i < count; i++)
            {
                float angle = baseAngle - halfSpread + angleStep * i;
                Vector2 dir = new Vector2(
                    Mathf.Cos(angle * Mathf.Deg2Rad),
                    Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnOne(spawnPos, dir, baseDamage, speed, ownerType, caster);
            }
        }
    }

    private void SpawnOne(Vector3 pos, Vector2 dir, float dmg, float spd,
                                  Projectile.OwnerType owner, ISkillCaster caster)
    {
        GameObject go = Instantiate(projectilePrefab, pos, Quaternion.identity);
        Projectile proj = go.GetComponent<Projectile>();
        if (proj == null) proj = go.AddComponent<Projectile>();
        proj.Initialize(dir, spd, dmg, owner, caster.CasterTransform.gameObject);
    }
}

using UnityEngine;

/// <summary>
/// 范围伤害技能效果：以施法者或目标点为中心造成圆形范围伤害。
/// 右键 -> Create -> Game -> Skill Effect -> AoE Damage
/// </summary>
[CreateAssetMenu(fileName = "AoEEffect", menuName = "Game/Skill Effect/AoE Damage")]
public class AoESkillEffect : SkillEffectBase
{
    [Header("范围配置")]
    [Tooltip("伤害半径")]
    public float radius = 3f;

    [Tooltip("是否以施法者为中心（否则以施法方向前方2单位处为中心）")]
    public bool centeredOnCaster = true;

    [Tooltip("打击特效预制体（可选）")]
    public GameObject impactVfx;

    [Header("预警（可选）")]
    [Tooltip("预警时间（秒），>0 则延迟生效并播放预警特效")]
    public float warningDuration;

    [Tooltip("预警特效（可选，须配合 warningDuration 使用）")]
    public GameObject warningVfx;

    [Header("眩晕（可选）")]
    [Tooltip("玩家被击中后眩晕时间（秒），0=不眩晕")]
    public float stunDuration;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 center = centeredOnCaster
            ? (Vector2)caster.CasterTransform.position
            : (Vector2)caster.CasterTransform.position + direction * 2f;

        float damage = caster.GetAttackStrength() * damageMultiplier;

        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono != null)
            mono.StartCoroutine(DelayedExecute(center, damage, ownerType));
        else
            ApplyDamage(center, damage, ownerType);
    }

    private System.Collections.IEnumerator DelayedExecute(Vector2 center,
        float damage, Projectile.OwnerType ownerType)
    {
        if (warningVfx != null)
            Object.Instantiate(warningVfx, center, Quaternion.identity);

        if (warningDuration > 0f)
            yield return new WaitForSeconds(warningDuration);

        ApplyDamage(center, damage, ownerType);
    }

    private void ApplyDamage(Vector2 center, float damage, Projectile.OwnerType ownerType)
    {
        if (impactVfx != null)
            Object.Instantiate(impactVfx, center, Quaternion.identity);

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, radius);
        string enemyTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";

        foreach (var hit in hits)
        {
            if (!hit.CompareTag(enemyTag)) continue;
            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(damage);

            if (stunDuration > 0f && hit.CompareTag("Player")
                && hit.TryGetComponent<PlayerController>(out var pc))
                pc.StartCoroutine(StunRoutine(pc, stunDuration));
        }
    }

    private static System.Collections.IEnumerator StunRoutine(PlayerController pc, float duration)
    {
        pc.InputLocked = true;
        yield return new WaitForSeconds(duration);
        pc.InputLocked = false;
    }
}

